const today = new Date().toISOString().split('T')[0];
const normalize = s => (s||'').toString().trim().toUpperCase().replace(/[\s_-]/g,'');
const rows = $input.all().map(r => r.json);
const dueToday  = rows.filter(r => normalize(r['Status'])==='SCHEDULEDMANUAL' && r['Publish Date']===today);
const overdue   = rows.filter(r => normalize(r['Status'])==='SCHEDULEDMANUAL' && r['Publish Date']<today);
const missingUrl= rows.filter(r => normalize(r['Status'])==='POSTEDMANUAL' && !(r['LinkedIn URL']||r['Facebook URL']||r['Instagram URL']));
return [{json:{today,dueToday,overdue,missingUrl,
  hasDue:dueToday.length>0, hasOverdue:overdue.length>0, hasMissing:missingUrl.length>0}}];

const d = $input.first().json;
const sheetUrl='https://docs.google.com/spreadsheets/d/1djoz4p-YyJ4Pu43-f9dUjWu4VhY6BCt-uUVMVVdK620/edit?gid=141580119';
const esc = s => String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const nl2br = s => esc(s).replace(/\n/g,'<br>');

let cardsHtml = '';
for(const row of d.dueToday){
  cardsHtml += `<div style="border:1px solid #e0e0e0;border-radius:10px;padding:20px;margin-bottom:24px;background:#fff;">
    <h3 style="margin:0 0 4px 0;font-size:15px;color:#1d1c84;">${esc(row['Row ID'])} &mdash; ${esc(row['Product Education']||row['Theme']||'')}</h3>
    <p style="margin:0 0 14px 0;font-size:12px;color:#888;"><strong>Pillar:</strong> ${esc(row['Content Pillar'])} &nbsp;&bull;&nbsp; <strong>Audience:</strong> ${esc(row['Audience'])}</p>
    <div style="background:#f0f4ff;border-left:4px solid #0077b5;padding:11px 14px;margin-bottom:9px;border-radius:0 6px 6px 0;">
      <div style="font-weight:bold;color:#0077b5;font-size:12px;margin-bottom:5px;">&#128188; LINKEDIN</div>
      <div style="font-size:13px;line-height:1.7;">${nl2br(row['LinkedIn Draft']||'(none)')}</div>
    </div>
    <div style="background:#f0f4ff;border-left:4px solid #1877f2;padding:11px 14px;margin-bottom:9px;border-radius:0 6px 6px 0;">
      <div style="font-weight:bold;color:#1877f2;font-size:12px;margin-bottom:5px;">&#128216; FACEBOOK</div>
      <div style="font-size:13px;line-height:1.7;">${nl2br(row['Facebook Draft']||'(none)')}</div>
    </div>
    <div style="background:#fff0f5;border-left:4px solid #e1306c;padding:11px 14px;margin-bottom:9px;border-radius:0 6px 6px 0;">
      <div style="font-weight:bold;color:#e1306c;font-size:12px;margin-bottom:5px;">&#128248; INSTAGRAM</div>
      <div style="font-size:13px;line-height:1.7;">${nl2br(row['Instagram Caption']||'(none)')}</div>
    </div>
    <div style="background:#fffbea;border:1px solid #f5d040;border-radius:6px;padding:9px 14px;margin-bottom:9px;font-size:12px;color:#555;">
      <strong>&#127912; Image Brief:</strong> ${esc(row['Image Brief']||'(none)')}<br>
      <strong>&#128279; CTA:</strong> ${esc(row['CTA']||'(none)')}
    </div>
    <div style="background:#f0f7f0;border-radius:6px;padding:10px 14px;font-size:12px;color:#333;line-height:2;">
      <strong>&#9989; Publishing checklist:</strong><br>
      &#9744; Post on LinkedIn &rarr; paste live URL into <strong>LinkedIn URL</strong> column<br>
      &#9744; Post on Facebook &rarr; paste live URL into <strong>Facebook URL</strong> column<br>
      &#9744; Post on Instagram &rarr; paste live URL into <strong>Instagram URL</strong> column<br>
      &#9744; Set <strong>Status = POSTED_MANUAL</strong><br>
      &#9744; Fill <strong>Posted By</strong> + <strong>Last Updated At</strong>
    </div>
  </div>`;
}

let overdueHtml = '';
if(d.hasOverdue){
  overdueHtml = `<div style="background:#fff5e6;border:1px solid #f5a623;border-radius:8px;padding:14px 18px;margin-bottom:16px;">
    <strong style="color:#c47000;">&#9888;&#65039; Overdue (${d.overdue.length} row(s))</strong>
    <ul style="margin:8px 0 0 0;padding-left:18px;font-size:13px;color:#555;">
      ${d.overdue.map(r=>`<li>${esc(r['Row ID'])} &mdash; ${esc(r['Product Education']||r['Theme']||'')} <span style="color:#c47000;">(was due ${esc(r['Publish Date'])})</span></li>`).join('')}
    </ul>
  </div>`;
}

const html = `<!DOCTYPE html><html><body style="font-family:Arial,Helvetica,sans-serif;background:#f4f4f7;margin:0;padding:24px;">
  <div style="max-width:680px;margin:0 auto;">
    <div style="background:#1d1c84;border-radius:10px 10px 0 0;padding:20px 28px;">
      <h2 style="color:#fff;margin:0;font-size:18px;">&#128197; ${d.dueToday.length} Post(s) to Publish Today &mdash; ${d.today}</h2>
      <p style="color:#b0b8ff;margin:4px 0 0 0;font-size:12px;">Carematix Manual Publishing Checklist</p>
    </div>
    <div style="background:#f9f9fb;padding:24px 28px;border:1px solid #e0e0e0;border-top:none;">
      ${overdueHtml}
      ${cardsHtml}
    </div>
    <div style="background:#fff;border:1px solid #e0e0e0;border-top:none;border-radius:0 0 10px 10px;padding:14px 28px;text-align:center;font-size:12px;color:#999;">
      <a href="${sheetUrl}" style="color:#1d1c84;font-weight:bold;">&#8594; Open Content Queue</a> &nbsp;|&nbsp; Carematix Automation System
    </div>
  </div>
</body></html>`;

return [{json:{subject:`&#128197; ${d.dueToday.length} post(s) to publish today (${d.today})`, body:html}}];
